67	// search performs a v4 query-serve search across every cell that hosts the
68	// caller's in-scope repos, then merges the per-cell responses into one
69	// response. It is the semantic sibling of searchAllCells (code): resolve
70	// scope → group by hosting cell → one query-serve call per cell → tiered
71	// merge.
72	//
73	// Scope follows Config.ScopeSlugs — an explicit repo filter wins over
74	// --all-repos (the more specific filter scopes the search):
75	//   - unfiltered (repo:* / --all-repos with no explicit filter) → every cell
76	//     is queried with NO repo param, so query-serve returns everything the
77	//     caller's token authorizes there (matching the BFF and keeping the query
78	//     small for users with many repos).
79	//   - explicit repo filter(s) or the current-repo default → the slugs are
80	//     resolved via truncation-proof exact-match lookups and each cell is
81	//     scoped to the ULIDs it hosts.
82	//
83	// Completeness caveats (truncated index, failed regions) are returned as
84	// Response.Warnings for the caller to surface.
85	func (s *semanticSearchV4Session) search(ctx context.Context, cfg search.Config) (*search.Response, error) {
86		if err := search.ValidateRepoFilters(cfg.Repos); err != nil {
87			return nil, err //nolint:wrapcheck // user-facing validation message
88		}
89	
90		coreClient, err := s.client()
91		if err != nil {
92			if errors.Is(err, auth.ErrNotLoggedIn) {
93				return nil, loginHintErr(err)
94			}
95			return nil, fmt.Errorf("semantic search: resolving control-plane client: %w", err)
96		}
97	
98		slugs, allRepos := cfg.ScopeSlugs()
99		var cells []cellGroup
100		var skipped []string
101		var warnings []string
102		indexTruncated := false
103		scoped := !allRepos
104		if scoped {
105			if len(slugs) == 0 {
106				return nil, errors.New("semantic search: could not determine the repository to search")
107			}
108			entries, err := s.resolveScope(ctx, slugs)
109			if err != nil {
110				return nil, err
111			}
112			// Scoped requests pin the picked placement's ULID (repoIDs below),
113			// which query-serve resolves from its all-accessible byID set.
114			cells, skipped = groupReposByCell(entries)
115		} else {
116			index, err := s.listFullIndex(ctx)
117			if err != nil {
118				return nil, fmt.Errorf("semantic search: listing repos for cell discovery: %w", err)
119			}
120			if index.Truncated {
121				// Debug, not Warn: the user-facing channel is the Warnings entry;
122				// slog's default handler would print a Warn straight to stderr on
123				// commands whose context carries no logger.
124				logging.Debug(ctx, "semantic search: repo index truncated; cross-repo results may be incomplete")
125				warnings = append(warnings, "repo index truncated; cross-repo results may be incomplete")
126				indexTruncated = true
127			}
128			// Broad requests send no repo pins; query-serve narrows pin-less
129			// scope by the same election routedRepoPlacement picks by (ENT-1776),
130			// so one grouping serves both request shapes.
131			cells, skipped = groupReposByCell(index.Repos)
132		}
133		skipped = reportableSkippedRepos(ctx, scoped, len(cells), skipped)
134		if len(skipped) > 0 {
135			warnings = append(warnings, fmt.Sprintf("skipped %d repo(s) with no searchable placement (missing or not ready): %s", len(skipped), strings.Join(skipped, ", ")))
136		}
137		// The BFF's scope-loss channels (search.ts): a truncated repo index means
138		// broad coverage silently misses repos; an explicitly-filtered repo
139		// skipped as not-ready narrows the promised scope. Unfiltered skips stay
140		// silent — nothing advertised was narrowed.
141		scopeNarrowed := scoped && len(skipped) > 0
142	
143		if len(cells) == 0 {
144			resp := &search.Response{Results: []search.Result{}, Page: 1, Warnings: warnings, Counts: &search.TypeCounts{}}
145			if indexTruncated {
146				// Every facet count is a lower bound, not an exact zero — same
147				// contract as the BFF's zero-routable-cells answer.
148				resp.Truncated = true
149				resp.CountsLowerBound = map[string]bool{
150					facetRepos: true, facetCheckpoints: true, facetCommits: true, facetPRs: true, facetSessions: true,
151				}
152			}
153			if indexTruncated || scopeNarrowed {
154				resp.Partial = true
155				resp.CoverageIncomplete = true
156			}
157			return resp, nil
158		}
159		resolveCellBaseURLs(ctx, s.clusterClient(coreClient), cells)
160	
161		results, err := fanOutCells(ctx, s.insecureHTTP, semanticSearchV4CellTimeout, cells, func(ctx context.Context, group cellGroup, client *api.Client) (*search.Response, error) {
162			// Scoped: restrict the cell to the ULIDs it hosts. Unfiltered: send no
163			// repo param and let query-serve search everything the token
164			// authorizes in that cell (avoids per-request repo-filter caps for
165			// large accounts).
166			var repoIDs []string
167			if scoped {
168				repoIDs = group.repoIDs
169			}
170			return search.CellV4(ctx, client, cfg, repoIDs)
171		})
172		if err != nil {
173			if errors.Is(err, auth.ErrNotLoggedIn) {
174				return nil, loginHintErr(err)
175			}
176			return nil, fmt.Errorf("semantic search: %w", err)
177		}
178	
179		resp, err := mergeSemanticV4Responses(ctx, cfg.Limit, cfg.Page, results)
180		if err != nil {
181			return nil, err
182		}
183		resp.Warnings = append(warnings, resp.Warnings...)
184		if indexTruncated {
185			resp.Truncated = true
186		}
187		if indexTruncated || scopeNarrowed {
188			resp.Partial = true
189			resp.CoverageIncomplete = true
190		}
191		return resp, nil
192	}
