227	// resolveScope resolves explicit repo filters (or the current-repo default)
228	// to index entries, deduped by repo ID. owner/name slugs use the exact-match
229	// ListRepos filter — immune to index truncation on large accounts — while raw
230	// IDs (no slash) fall back to matching against the full index. Zero matches
231	// is a clear error; a partially matched multi-repo filter proceeds with the
232	// matches, like resolveRepoFilters does for code search.
233	func (s *semanticSearchV4Session) resolveScope(ctx context.Context, slugs []string) ([]coreapi.RepoIndexEntry, error) {
234		var entries []coreapi.RepoIndexEntry
235		seen := make(map[string]bool, len(slugs))
236		for _, f := range slugs {
237			matched, err := s.lookupFilter(ctx, f)
238			if err != nil {
239				return nil, err
240			}
241			for _, e := range matched {
242				if !seen[e.ID] {
243					seen[e.ID] = true
244					entries = append(entries, e)
245				}
246			}
247		}
248		if len(entries) == 0 {
249			return nil, fmt.Errorf("no matching repositories found for %v (is the repo mirrored to Entire?)", slugs)
250		}
251		return entries, nil
252	}
