542	// Facet names for the wire maps (truncated_types / counts_lower_bound) — the
543	// BFF's RESULT_TYPE_TO_FACET values.
544	const (
545		facetRepos       = "repos"
546		facetCheckpoints = "checkpoints"
547		facetCommits     = "commits"
548		facetPRs         = "prs"
549		facetSessions    = "sessions"
550	)
