552	// semanticFacetOf maps a wire result type to its counts/truncation facet name
553	// (the BFF's RESULT_TYPE_TO_FACET). Unknown types have no facet: they are kept
554	// in results, exempt from the per-type cap, and counted only in the total.
555	func semanticFacetOf(typ string) (string, bool) {
556		switch typ {
557		case search.TypeRepo:
558			return facetRepos, true
559		case search.TypeCheckpoint:
560			return facetCheckpoints, true
561		case search.TypeCommit:
562			return facetCommits, true
563		case search.TypePR:
564			return facetPRs, true
565		case search.TypeSession:
566			return facetSessions, true
567		}
568		return "", false
569	}
570	
571	// capSemanticPerType applies the BFF's per-type window: walk the merged list
572	// in order and keep at most `limit` rows of each facet, recording which facets
573	// overflowed. Rows without a facet mapping are kept uncounted.
574	func capSemanticPerType(merged []search.Result, limit int) ([]search.Result, map[string]bool) {
575		truncated := make(map[string]bool)
576		if limit <= 0 {
577			return merged, truncated
578		}
579		perFacet := make(map[string]int, 5)
580		out := merged[:0]
581		for _, r := range merged {
582			facet, ok := semanticFacetOf(r.Type)
583			if !ok {
584				out = append(out, r)
585				continue
586			}
587			perFacet[facet]++
588			if perFacet[facet] > limit {
589				truncated[facet] = true
590				continue
591			}
592			out = append(out, r)
593		}
594		return out, truncated
595	}
596	
597	// deriveSemanticCounts computes total and per-type counts from the FINAL
598	// merged list — the BFF's per-type contract (ENT-1363): counts describe
599	// exactly what the caller can see, never the cells' corpus-count passes,
600	// with counts_lower_bound marking the facets whose lists were capped.
601	func deriveSemanticCounts(merged []search.Result) (int, *search.TypeCounts) {
602		counts := &search.TypeCounts{}
603		for _, r := range merged {
604			switch r.Type {
605			case search.TypeRepo:
606				counts.Repos++
607			case search.TypeCheckpoint:
608				counts.Checkpoints++
609			case search.TypeCommit:
610				counts.Commits++
611			case search.TypePR:
612				counts.PRs++
613			case search.TypeSession:
614				counts.Sessions++
615			}
616		}
617		return len(merged), counts
618	}
