636	//     keys keep cell-response order.
637	//  3. Dedupe AFTER ordering, BEFORE the per-type cap, sessions only, first
638	//     (highest-ranked) copy wins (dedupSemanticResults).
639	//  4. Per-type window: at most `limit` rows of each facet, overflow recorded
640	//     in truncated_types, unioned with the cells' own truncated_types
641	//     (capSemanticPerType). No global cut.
642	//  5. Counts and total derive from the FINAL list (deriveSemanticCounts);
643	//     counts_lower_bound == the capped facets.
644	//  6. Flags: truncated = any cell truncated; partial = truncated ∨ any cell
645	//     failed ∨ any cell partial ∨ mixed rerank capability; coverage_incomplete
646	//     = the same minus rerank-mix; reranked = every cell reranked (emitted
647	//     when any cell reported the field).
648	//
649	// Rerank scores share a space across cells (same Cohere model), so
650	// interleaving is meaningful. All-cells-failed is an error; a partial failure
651	// is noted in Warnings (and the flags) and the surviving cells are merged.
652	func mergeSemanticV4Responses(ctx context.Context, limit, page int, results []cellCallResult[*search.Response]) (*search.Response, error) {
653		pages, failed, lastErr := classifySemanticCells(ctx, results)
654		if len(pages) == 0 {
655			if lastErr != nil {
656				return nil, fmt.Errorf("semantic search: %w", lastErr)
657			}
658			return &search.Response{Results: []search.Result{}, Page: 1}, nil
659		}
660		var warnings []string
661		if len(failed) > 0 {
662			// Debug, not Warn: the warning below already reaches the user via
663			// Response.Warnings, and slog's default handler would print a Warn
664			// straight to stderr on commands whose context carries no logger.
665			logging.Debug(ctx, "semantic search: partial failure; results may be incomplete",
666				"succeeded", len(pages), "total", len(results), "failed_cells", failed)
667			warnings = append(warnings, fmt.Sprintf("search failed in %d of %d regions; results may be incomplete", len(failed), len(pages)+len(failed)))
668		}
669	
670		merged := rankSemanticResults(pages)
671		merged = dedupSemanticResults(merged)
672		merged, truncatedTypes := capSemanticPerType(merged, limit)
673		for _, p := range pages {
674			for facet, v := range p.body.TruncatedTypes {
675				if v {
676					truncatedTypes[facet] = true
677				}
678			}
679		}
680		if merged == nil {
681			merged = []search.Result{}
682		}
683	
684		total, counts := deriveSemanticCounts(merged)
685		resp := &search.Response{
686			Results:  merged,
687			Total:    total,
688			Page:     max(page, 1),
689			Counts:   counts,
690			Warnings: warnings,
691		}
692		if len(truncatedTypes) > 0 {
693			resp.TruncatedTypes = truncatedTypes
694			resp.CountsLowerBound = make(map[string]bool, len(truncatedTypes))
695			for facet := range truncatedTypes {
696				resp.CountsLowerBound[facet] = true
697			}
698		}
699	
700		anyRerankedField, anyReranked, allReranked := false, false, true
701		for _, p := range pages {
702			if p.body.Truncated {
703				resp.Truncated = true
704			}
705			if p.body.Partial {
706				resp.Partial = true
707				resp.CoverageIncomplete = true
708			}
709			if p.body.Reranked != nil {
710				anyRerankedField = true
711				if *p.body.Reranked {
712					anyReranked = true
713				} else {
714					allReranked = false
715				}
716			} else {
717				allReranked = false
718			}
719		}
720		if len(failed) > 0 || resp.Truncated {
721			resp.Partial = true
722			resp.CoverageIncomplete = true
723		}
724		if anyReranked && !allReranked {
725			// Mixed rerank capability skews ordering but not coverage — partial
726			// without coverage_incomplete, matching the BFF.
727			resp.Partial = true
728		}
729		if anyRerankedField {
